func:
// 어댑터 코드(V1 도 직접 짠 범위: 연결·변환). HR 0~23(24워드) → float32 ABCD 12개 → EdgeX Event v3 모양.
const TAGS = ["LT-101","LT-102","TT-101","TT-102","PT-101","FT-101","FT-102","IT-101","IT-102","VT-101","pH-101","CT-101"];
const UNITS = {"LT-101":"%","LT-102":"%","TT-101":"degC","TT-102":"degC","PT-101":"barg","FT-101":"m3/h","FT-102":"m3/h","IT-101":"A","IT-102":"A","VT-101":"mm/s","pH-101":"pH","CT-101":"mS/cm"};
const r = msg.payload;
if (!Array.isArray(r) || r.length < 24) { return null; }
const buf = Buffer.alloc(4);
const origin = Date.now() * 1000000;
const readings = TAGS.map((t, i) => {
  buf.writeUInt16BE(r[2 * i] & 0xffff, 0);
  buf.writeUInt16BE(r[2 * i + 1] & 0xffff, 2);
  const v = buf.readFloatBE(0);
  return {origin: origin, deviceName: "reactor-line-01", resourceName: t, profileName: "AR100-Reactor-Line",
          valueType: "Float32", units: UNITS[t], value: v.toExponential(7)};
});
msg.topic = "edgex/telemetry";
msg.payload = {apiVersion: "v3", deviceName: "reactor-line-01", profileName: "AR100-Reactor-Line",
               sourceName: "AllSensors", origin: origin, readings: readings};
return msg;
